// Potential Memory Leak:
let cachedButton;
function setup() {
  const btn = document.querySelector('#action-btn');
  cachedButton = btn; // Global reference held!
  btn.remove();        // Removed from DOM, but still in heap
}

// Fix: Nullify reference when element is detached
function cleanup() {
  cachedButton = null;
}

