const parentCheckbox = document.querySelector('#select-all');
const childCheckboxes = document.querySelectorAll('.child-check');

function updateParentState() {
  const checkedCount = [...childCheckboxes].filter(c => c.checked).length;
  if (checkedCount === 0) {
    parentCheckbox.checked = false;
    parentCheckbox.indeterminate = false;
  } else if (checkedCount === childCheckboxes.length) {
    parentCheckbox.checked = true;
    parentCheckbox.indeterminate = false;
  } else {
    parentCheckbox.checked = false;
    parentCheckbox.indeterminate = true; // Partially selected!
  }
}

