function parseDataConfig(element) {
  const raw = element.getAttribute('data-config');
  if (!raw) return null;
  try {
    const data = JSON.parse(raw);
    return typeof data === 'object' && data !== null ? data : null;
  } catch (err) {
    console.warn('Malformed JSON in data-config attribute:', err);
    return null;
  }
}

