let sanitizerPolicy;

if (window.trustedTypes) {
  sanitizerPolicy = window.trustedTypes.createPolicy('default', {
    createHTML: (dirty) => DOMPurify.sanitize(dirty),
    createScript: () => { throw new Error('Inline script generation forbidden'); },
    createScriptURL: (url) => {
      if (url.startsWith('https://trusted-cdn.example.com/')) return url;
      throw new Error('Untrusted script source');
    }
  });
}

// Safe sink mutation:
const safeHTML = sanitizerPolicy ? sanitizerPolicy.createHTML(userInput) : DOMPurify.sanitize(userInput);
container.innerHTML = safeHTML;

