const ROW_HEIGHT = 40;
const VISIBLE_COUNT = 25;
const BUFFER = 5;
const totalItems = 50000;

const viewport = document.querySelector('#viewport');
const spacer = document.querySelector('#spacer');
const content = document.querySelector('#content');

spacer.style.height = `${totalItems * ROW_HEIGHT}px`;

function renderWindow() {
  const scrollTop = viewport.scrollTop;
  const start = Math.max(0, Math.floor(scrollTop / ROW_HEIGHT) - BUFFER);
  const end = Math.min(totalItems, start + VISIBLE_COUNT + (BUFFER * 2));

  content.style.transform = `translateY(${start * ROW_HEIGHT}px)`;
  content.replaceChildren();
  for (let i = start; i < end; i++) {
    const row = document.createElement('div');
    row.className = 'virtual-row';
    row.textContent = `Row #${i + 1}: Data item`;
    content.appendChild(row);
  }
}
viewport.addEventListener('scroll', () => requestAnimationFrame(renderWindow));
renderWindow();

