const tabList = document.querySelector('[role="tablist"]');
const tabs = [...tabList.querySelectorAll('[role="tab"]')];
const panels = [...document.querySelectorAll('[role="tabpanel"]')];

function switchTab(newTab) {
  tabs.forEach(tab => {
    const isTarget = tab === newTab;
    tab.setAttribute('aria-selected', isTarget);
    tab.tabIndex = isTarget ? 0 : -1;
  });
  panels.forEach(p => p.hidden = p.id !== newTab.getAttribute('aria-controls'));
  newTab.focus();
}

tabList.addEventListener('keydown', (e) => {
  let index = tabs.indexOf(document.activeElement);
  if (index === -1) return;
  if (e.key === 'ArrowRight') switchTab(tabs[(index + 1) % tabs.length]);
  if (e.key === 'ArrowLeft') switchTab(tabs[(index - 1 + tabs.length) % tabs.length]);
});

