let state = { data: allUsers, query: '', sortCol: 'name', sortAsc: true, page: 1, perPage: 10 };

function getFilteredData() {
  return state.data
    .filter(u => u.name.toLowerCase().includes(state.query.toLowerCase()))
    .sort((a, b) => {
      const valA = a[state.sortCol], valB = b[state.sortCol];
      return (valA < valB ? -1 : 1) * (state.sortAsc ? 1 : -1);
    });
}

function renderTable() {
  const filtered = getFilteredData();
  const pageData = filtered.slice((state.page - 1) * state.perPage, state.page * state.perPage);
  const frag = document.createDocumentFragment();
  pageData.forEach(row => {
    const tr = document.createElement('tr');
    tr.innerHTML = `<td>${row.id}</td><td>${row.name}</td><td>${row.role}</td>`;
    frag.appendChild(tr);
  });
  document.querySelector('#table-body').replaceChildren(frag);
}

