function makeInlineEditable(element, onSave) {
  element.addEventListener('click', () => {
    const originalVal = element.textContent;
    const input = document.createElement('input');
    input.type = 'text';
    input.value = originalVal;
    let isCancelled = false;

    input.addEventListener('keydown', (e) => {
      if (e.key === 'Enter') input.blur();
      if (e.key === 'Escape') { isCancelled = true; input.blur(); }
    });

    input.addEventListener('blur', () => {
      const finalVal = isCancelled ? originalVal : input.value.trim() || originalVal;
      element.textContent = finalVal;
      input.replaceWith(element);
      if (!isCancelled && finalVal !== originalVal) onSave(finalVal);
    });

    element.replaceWith(input);
    input.focus();
    input.select();
  });
}

