const tagContainer = document.querySelector('#tags-wrapper');
const input = document.querySelector('#tag-input');
const tags = new Set();

function addTag(text) {
  const clean = text.trim().toLowerCase();
  if (!clean || tags.has(clean)) return;
  tags.add(clean);
  const chip = document.createElement('span');
  chip.className = 'tag-chip';
  chip.innerHTML = `${clean} <button type="button" class="remove-tag">&times;</button>`;
  tagContainer.insertBefore(chip, input);
  input.value = '';
}

input.addEventListener('keydown', (e) => {
  if (e.key === 'Enter' || e.key === ',') {
    e.preventDefault();
    addTag(input.value);
  } else if (e.key === 'Backspace' && !input.value) {
    const lastTag = input.previousElementSibling;
    if (lastTag) { tags.delete(lastTag.textContent.slice(0, -1).trim()); lastTag.remove(); }
  }
});

