const svgMap = document.querySelector('#seat-map');
const totalEl = document.querySelector('#total-price');
let selectedSeats = new Map();

svgMap.addEventListener('click', (e) => {
  const seat = e.target.closest('.seat:not(.occupied)');
  if (!seat) return;

  const seatId = seat.dataset.seatId;
  const price = Number(seat.dataset.price);

  if (selectedSeats.has(seatId)) {
    selectedSeats.delete(seatId);
    seat.classList.remove('selected');
  } else {
    selectedSeats.set(seatId, price);
    seat.classList.add('selected');
  }

  const total = [...selectedSeats.values()].reduce((sum, p) => sum + p, 0);
  totalEl.textContent = `$${total}`;
});

