const editor = document.querySelector('#md-input');
const preview = document.querySelector('#md-preview');

editor.addEventListener('input', () => {
  const rawMarkdown = editor.value;
  const rawHtml = marked.parse(rawMarkdown); // Parse markdown
  const safeHtml = DOMPurify.sanitize(rawHtml); // 100% XSS safe
  preview.innerHTML = safeHtml;
});

