let warningTimer, logoutTimer;
const WARNING_MS = 14 * 60 * 1000;
const LOGOUT_MS = 15 * 60 * 1000;

function resetInactivity() {
  clearTimeout(warningTimer);
  clearTimeout(logoutTimer);
  hideWarningModal();

  warningTimer = setTimeout(showWarningModal, WARNING_MS);
  logoutTimer = setTimeout(performLogout, LOGOUT_MS);
}

['mousemove', 'keydown', 'click', 'scroll'].forEach(evt => {
  window.addEventListener(evt, throttle(resetInactivity, 1000), { passive: true });
});
resetInactivity();

