/* Pure CSS Sticky Header and Sticky First Column: */
.grid-container {
  overflow: auto;
  max-height: 500px;
}

thead th {
  position: sticky;
  top: 0;
  background: #f8fafc;
  z-index: 2;
}

td:first-child, th:first-child {
  position: sticky;
  left: 0;
  background: #f8fafc;
  z-index: 1;
}

/* Top-left corner cell stays above both: */
thead th:first-child {
  z-index: 3;
}

